    # Extend every diagonal line determined by two same-colored points.
    for i, (r, c, color) in enumerate(pts):
        for rr, cc, other in pts[i+1:]:
            if color != other or abs(rr-r) != abs(cc-c) or rr == r:
                continue
            dr = 1 if rr > r else -1
            dc = 1 if cc > c else -1
            # Fill the entire diagonal through both points to both grid boundaries.
            x, y = r, c
            while 0 <= x-dr < h and 0 <= y-dc < w:
                x, y = x-dr, y-dc
            while 0 <= x < h and 0 <= y < w:
                if out[x][y] == bg:
                    out[x][y] = color
                x += dr
                y += dc
    return out
